"use client";

import React, { useState } from "react";

const QUESTIONS: string[] = [
  "I feel motivated to learn new skills.",
  "I can manage my workload effectively.",
  "I receive useful feedback from mentors.",
  "I feel included by my team.",
  "I can ask for help when I need it.",
  "My goals for this internship are clear.",
  "I have the resources I need to do good work.",
  "I feel confident presenting my ideas.",
  "Overall, this internship is positively impacting me.",
];

type Props = {
  onSubmit?: (answers: number[]) => void;
};

export default function Questionnaire({ onSubmit }: Props) {
  const [answers, setAnswers] = useState<number[]>(Array(QUESTIONS.length).fill(0));
  const [submitted, setSubmitted] = useState(false);

  function updateAnswer(i: number, value: number) {
    const next = [...answers];
    next[i] = value;
    setAnswers(next);
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitted(true);
    try {
      onSubmit?.(answers);
    } catch (e) {}
  }

  const total = answers.reduce((s, v) => s + v, 0);
  const max = QUESTIONS.length * 5;
  const percent = Math.round((total / max) * 100);

  return (
    <section className="bg-white p-6 rounded-xl shadow">
      <h3 className="text-lg font-semibold text-[#0F766E]">9‑Question Check-In</h3>
      <p className="text-sm text-gray-600 mt-1">Choose a value from 1 (disagree) to 5 (strongly agree).</p>

      <form onSubmit={handleSubmit} className="mt-4 space-y-3">
        {QUESTIONS.map((q, i) => (
          <div key={i} className="flex flex-col">
            <label className="text-sm text-gray-800 mb-1">{i + 1}. {q}</label>
            <div className="flex gap-2">
              {[1,2,3,4,5].map((n) => (
                <button
                  key={n}
                  type="button"
                  onClick={() => updateAnswer(i, n)}
                  className={`px-3 py-1 rounded ${answers[i]===n ? 'bg-[#10B981] text-white' : 'bg-gray-100 text-gray-700'}`}
                >
                  {n}
                </button>
              ))}
            </div>
          </div>
        ))}

        <div className="flex items-center gap-3 mt-2">
          <button type="submit" className="px-4 py-2 rounded bg-[#064E3B] text-white">Submit</button>
          <button type="button" onClick={() => { setAnswers(Array(QUESTIONS.length).fill(0)); setSubmitted(false); }} className="px-3 py-2 rounded bg-gray-100">Reset</button>
        </div>
      </form>

      {submitted && (
        <div className="mt-4 p-3 border rounded bg-green-50">
          <p className="text-sm">Score: <strong>{total}</strong> / {max} ({percent}%)</p>
          <p className="text-xs text-gray-600">This is a lightweight check-in — for clinical assessments, use a validated survey.</p>
        </div>
      )}
    </section>
  );
}
